  assertNotArchived("Issue", issue.id, issue);
  const hierarchy = await issueRepo.listProjectHierarchy(input.orgId, issue.projectId);
  const subtree = descendants(hierarchy, issue.id);
  const height = subtree.reduce((max, node) => Math.max(max, node.depth), 0);
