  const queue = [{ id: issueId, depth: 0 }];
  const result: { issue: Issue; depth: number }[] = [];
  for (let index = 0; index < queue.length; index++) {
    const node = queue[index]"'!;
    for (const issue of children.get(node.id) ?? []) {
      if (seen.has(issue.id)) continue;
      seen.add(issue.id);
      const depth = node.depth + 1;
      result.push({ issue, depth });
      queue.push({ id: issue.id, depth });
    }
  }
  return result;
}

function validateParent(
  hierarchy: readonly Issue[],
  parentId: IssueId,
  issueId: IssueId,
  subtreeHeight: number,
  moving = false,
): void {
  const byId = new Map(hierarchy.map(issue => [issue.id, issue]));
  const parent = requireFound(byId.get(parentId), "Issue", parentId);
  assertNotArchived("Issue", parent.id, parent);
  const seen = new Set<IssueId>();
  let ancestor: Issue | undefined = parent;
  let depth = 0;
  while (ancestor) {
    if ((moving && ancestor.id === issueId) || seen.has(ancestor.id)) {
      throw new IssueHierarchyError(issueId, "cycle");
    }
    seen.add(ancestor.id);
    depth++;
    ancestor = ancestor.parentId === null ? undefined : byId.get(ancestor.parentId);
  }
  if (depth + subtreeHeight > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}

function isOpen(issue: Issue): boolean {
  return !CLOSED_ISSUE_STATUSES.includes(issue.status);
}

function rollup(hierarchy: readonly Issue[], issueId: IssueId): IssueRollup {
  const live = descendants(hierarchy, issueId).filter(node => node.issue.archivedAt === null);
  const open = live.filter(node => isOpen(node.issue)).length;
  return { total: live.length, open, closed: live.length - open };
}

/** Only closing transitions call this; no persisted completion marker is needed. */
async function notifyCompletedParents(
  actor: Actor,
  projectId: ProjectId,
  parentIds: readonly IssueId[],
): Promise<void> {
  if (parentIds.length === 0) return;
  const hierarchy = await issueRepo.listProjectHierarchy(actor.orgId, projectId);
  for (const parentId of new Set(parentIds)) {
    const parent = hierarchy.find(issue => issue.id === parentId);
    if (!parent || parent.archivedAt !== null || parent.assigneeId === null) continue;
    if (rollup(hierarchy, parent.id).open !== 0) continue;
    await notify(actor.orgId, "sub_issues_completed", [parent.assigneeId], {
      title: "All sub-issues completed",
      body: `All sub-issues of ${parent.title} are closed`,
      href: `/issues/${parent.id}`,
      actorId: actor.userId,
    });
  }
}

export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);
  const issue = requireFound(await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue", input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  const hierarchy = await issueRepo.listProjectHierarchy(input.orgId, issue.projectId);
  const subtree = descendants(hierarchy, issue.id);
  const height = subtree.reduce((max, node) => Math.max(max, node.depth), 0);
  if (input.parentId !== null) {
    validateParent(hierarchy, input.parentId, issue.id, height, true);
  } else if (height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issue.id, "too_deep");
  }
  if (issue.parentId === input.parentId) return issue;
  const after = await issueRepo.setIssueParent(input.orgId, issue.id, input.parentId);
  await emit("issue.updated", {
    ...actorEnvelope(actor), issueId: after.id, projectId: after.projectId,
    changedFields: ["parentId"],
  });
  return after;
}

export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
  assertCan(actor, "issue:read", issueResource(issue));
  const hierarchy = await issueRepo.listProjectHierarchy(orgId, issue.projectId);
  return hierarchy.filter(child => child.parentId === issue.id && child.archivedAt === null)
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.number - b.number);
}

export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
  assertCan(actor, "issue:read", issueResource(issue));
  return rollup(await issueRepo.listProjectHierarchy(orgId, issue.projectId), issue.id);
}
