    expect(await notices()).toHaveLength(0);
    await status(sibling.id, "canceled");
    expect(await notices()).toHaveLength(1);
    await status(sibling.id, "done");
    expect(await notices()).toHaveLength(1);
    await status(child.id, "todo");
